const icons={headset:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M4 14v-3a8 8 0 0 1 16 0v3M4 11H3a1 1 0 0 0-1 1v5a1 1 0 0 0 1 1h3v-7H4Zm16 0h1a1 1 0 0 1 1 1v5a1 1 0 0 1-1 1h-3v-7h2ZM19 18c0 3-3 4-6 4h-2"/></svg>',person:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="8" r="4"/><path d="M4 21c0-4.4 3.6-7 8-7s8 2.6 8 7"/></svg>',shield:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7"><path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6l8-3Z"/><path d="m8 12 3 3 5-6"/></svg>'};
const $=id=>document.getElementById(id),chat=$('chat'),input=$('message');
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const mascot='<img src="assets/support-mascot-v8.png" alt="Warm-cream gender-neutral support mascot wearing yellow headphones and a yellow cape, holding a fork and butter knife">';
const profileAvatar='<img src="assets/support-profile-v1.png" alt="" width="44" height="44">';
document.querySelectorAll('[data-icon]').forEach(e=>e.innerHTML=icons[e.dataset.icon]);
const rationale={
entry:['Opening screen','A calm, simple start',[
['Friendly mascot','Many people dread “talking to a bot.” A warm helper with a headset, cape and utensils tries to ease that feeling, so users feel welcomed instead of defensive.'],
['Just two choices','Aims to help users feel in control instead of overwhelmed.'],
['Order name on the button','Aims to help users feel sure they’re getting help with the right order.']]],
options:['First chat screen','Straight to the point',[
['Problem stated up front','Aims to help users feel understood without having to explain.'],
['Three clear options','Aims to help users feel in control of what happens next.'],
['Human agent always visible','Aims to help users feel safe knowing a person is one tap away.'],
['Progress bar and order chip','Aims to show users where they are at every step.']]],
contacting:['Contact my courier','Action, not waiting',[
['Message to the courier shown','Aims to show users exactly what’s being done for them.'],
['Latest arrival time and a promise to keep watching','Aims to reassure users rather than dismiss them.'],
['Clear choices if the courier is silent','Aims to make sure users never feel stuck.']]],
confirm:['Cancellation summary','Honest, never a dead end',[
['“Sorry about the wait” first','Aims to help users feel heard before they see any numbers.'],
['Clear amounts and the reason','Aims to help users feel treated fairly, with no surprises.'],
['A safety net if they keep the order','Aims to help users feel protected whichever they choose.']]],
waiting:['Order on its way','Close the loop',[
['A promise to keep watching','Aims to let users relax instead of checking the app.'],
['Single Done button','Aims to let users finish without extra decisions.']]],
receipt:['Resolution','Clear completion',[
['Amount, method and timing in plain words','Aims to help users feel certain it’s handled.'],
['Single Done button','Aims for a calm, decisive ending.']]],
summary:['Closing screen','End on a good feeling',[
['Celebrating mascot','Aims to leave users with relief and a positive last impression.'],
['Short thank-you and a light rating','Aims to help users feel appreciated, not burdened.']]],
free:['Something else','In your own words',[
['Free text, no categories','Aims to help users feel heard instead of forced into boxes.'],
['A person after two misunderstandings','Aims to keep users out of a frustrating bot loop.']]],
human:['Human handoff','No starting over',[
['Context passed to the agent','Aims to spare users from repeating themselves.'],
['Distinct person icon and status','Aims to make it clear who users are talking to.']]]};
function renderRationale(view){const key=['different','review','clarify'].includes(view)?'free':['handoff','agent'].includes(view)?'human':['processing','receipt'].includes(view)?'receipt':view;const r=rationale[key]||rationale.options;const list=`<ul>${r[2].map(([what,why])=>`<li><b>${what}</b><span>${why}</span></li>`).join('')}</ul>`;$('rationale-mobile-body').innerHTML=`<span class="eyebrow">${r[0].toUpperCase()}</span><h3>${r[1]}</h3>${list}`;$('rationale').innerHTML=`<span class="eyebrow">WHY IT’S DESIGNED THIS WAY · ${r[0].toUpperCase()}</span><h3>${r[1]}</h3><ul>${r[2].map(([what,why])=>`<li><b>${what}</b><span>${why}</span></li>`).join('')}</ul>`}
let model,timer;
function fresh(choice='active'){clearTimeout(timer);const scenario=choice==='past'?'past':'active';model={scenario,silent:choice==='silent',courier:'',view:'entry',stack:[],refund:false,processing:false,rating:0,topic:'',issue:'',unknowns:0,transcript:[],agentMessages:[],returnView:'options',notice:''};input.value='';$('scenario').value=choice;render()}
function log(who,text){model.transcript.push({who,text})}
function say(text){log('AI assistant',text)}
function go(view,{remember=true}={}){if(remember&&view!==model.view)model.stack.push(model.view);model.view=view;model.notice='';render();if(view!=='entry')chat.focus({preventScroll:true})}
function bot(text){return `<div class="message"><span class="avatar" aria-hidden="true">${profileAvatar}</span><div class="bubble">${text}</div></div>`}
function agent(text){return `<div class="message human-message"><span class="avatar agent-avatar" aria-hidden="true">${icons.person}</span><div class="bubble"><span class="sender">Jamie · Human support</span>${text}</div></div>`}
function courier(text){return `<div class="message courier-message"><span class="avatar courier-avatar" aria-hidden="true">A</span><div class="bubble"><span class="sender">Alex · Courier</span><p>${text}</p></div></div>`}
function actions(list){return `<div class="actions">${list.map(([id,label,primary])=>`<button class="${primary?'primary':'secondary'}" data-action="${id}">${label}<span aria-hidden="true">${primary?'→':'›'}</span></button>`).join('')}</div>`}
const escalate='<p class="escalate-note">Or, chat with a human agent using the top-right button anytime.</p>';
function progress(n,label){$('progress-fill').style.width=`${n/4*100}%`;$('progress').setAttribute('aria-valuenow',n);$('progress').setAttribute('aria-valuetext',`${label}, step ${n} of 4`)}
function orderId(){return model.scenario==='active'?'UE1042':'UE1038'}
function partial(){return model.courier==='replied'}
function refundAmount(){return partial()?'$6.35':'$24.80'}
function refundStatus(){return model.refund?`Order canceled; ${model.amount} refunded to the original payment method.`:model.processing?`Cancellation and ${refundAmount()} refund are being processed.`:model.cash?'Order kept; $5 Uber Cash added.':'No cancellation or refund has been made.'}
function currentIssue(){const base=model.issue||(model.topic&&model.topic!=='Delayed delivery'?model.topic:model.scenario==='active'?'Courier has not moved for more than 10 minutes.':'Customer requests help with a past order.');return model.courier==='replied'&&!model.refund?`${base} Update: the courier replied and is back on the way, about 8 minutes out.`:model.courier==='silent'&&!model.refund?`${base} The courier did not reply to a check-in message.`:base}
function contextCard(){return `<div class="handoff-card"><div class="handoff-label">YOUR CONTEXT GOES WITH YOU</div><dl><dt>Order</dt><dd>#${orderId()} · Sweetgreen</dd><dt>What happened</dt><dd>${esc(currentIssue())}</dd><dt>Action so far</dt><dd>${esc(refundStatus())}</dd></dl><div class="handoff-check">✓ Full conversation included · ${model.transcript.filter(m=>m.who==='You').length} customer message(s)</div></div>`}
function updateOrder(){const past=model.scenario==='past';$('order-label').textContent=past?'YOUR PAST ORDER':'YOUR CURRENT ORDER';$('order-meta').textContent=`${past?'Yesterday':'Today'}, 12:32 PM · Order #${orderId()}`;$('receipt-meta').textContent=`Sample order #${orderId()} · Sweetgreen`;$('delivery-status').textContent=model.refund?`Order canceled · ${model.amount} refunded`:past?'Delivered yesterday at 1:08 PM':(model.courier==='replied'?'Courier is moving again · about 8 min away':'Courier hasn’t moved for 12 minutes')+' · Latest arrival 1:05 PM';document.querySelector('.route').classList.toggle('past-order',past);$('order-help').innerHTML=model.view==='entry'?'Get help <span>→</span>':'Return to support <span>→</span>';$('chip-order').textContent=`Sweetgreen · #${orderId()}`;$('chip-status').textContent=model.refund?'Canceled':past?'Delivered':model.courier==='replied'?'~8 min away':'Delayed';$('order-chip').classList.toggle('is-ok',model.refund||past||model.courier==='replied')}
function render(){updateOrder();let view=model.view;if(view==='welcome')view=model.view='options';if(model.refund&&['options','confirm','contacting','waiting','processing'].includes(view)){view=model.view='receipt'}
const human=['handoff','agent'].includes(view),entry=view==='entry',closed=view==='summary';
document.body.classList.toggle('support-active',!entry);document.querySelector('.support').classList.toggle('is-entry',entry);document.querySelector('.support').classList.toggle('is-resolved',closed);
$('support-presence').innerHTML=view==='agent'?'<i></i> Jamie · Online':view==='handoff'?'<i class="pending"></i> Connecting you to a person…':'<i></i> AI assistant · Online';
$('human').classList.toggle('is-connected',human);$('human').setAttribute('aria-disabled',human);$('human-label').innerHTML=view==='agent'?'Connected<br>to a person':view==='handoff'?'Connecting<br>to a person':'Request<br>human agent';$('order-chip').hidden=entry;$('back').disabled=entry||model.processing;
document.querySelector('.progress-wrap').hidden=entry||human;progress(closed?4:['processing','receipt','waiting'].includes(view)?3:['confirm','contacting','review','clarify'].includes(view)?2:1,closed?'Resolved':['processing','receipt','waiting'].includes(view)?'Making it right':['confirm','contacting','review','clarify'].includes(view)?'Choosing a solution':'Understanding your issue');
$('composer').hidden=entry||closed;input.disabled=model.processing;document.querySelector('#composer button').disabled=model.processing;input.placeholder=view==='agent'?'Message Jamie…':'Tell us in your own words…';$('reassurance').textContent=entry?'Help starts with your order.':closed?'We’re here if you need anything else.':human?'You won’t need to start over.':'';
let html='';
if(entry){html=`<div class="support-entry"><div class="entry-art">${mascot}</div><h3 id="entry-greeting">Let’s get you the help you need.<span>Where should we start?</span></h3><div class="entry-choices" role="group" aria-labelledby="entry-greeting"><button class="primary full entry-choice" data-action="start"><span class="choice-text">Get help with this order<small>Sweetgreen · #${orderId()}</small></span><span aria-hidden="true">→</span></button><button class="secondary full entry-choice" data-action="elsewhere"><span class="choice-text">Get help with something else</span><span aria-hidden="true">›</span></button></div></div>`}
if(view==='options'){html=bot('<p>Your courier <b>hasn’t moved in over 10 minutes.</b> Sorry about that.</p><p>Here’s what I can do right now:</p>')+actions([['contact','Contact my courier'],['cancel','Cancel this order'],['different','Something else']])+escalate}
if(view==='confirm'){html=partial()?bot('<p>Sorry about the wait. Your food is already made and on its way, so cancelling now can’t be fully refunded.</p>')+`<div class="outcome-card"><dl><dt>If you cancel</dt><dd>Your order is canceled and Alex is notified. You get <b>$6.35</b> back for delivery, fees and tax, usually within 3–10 business days.</dd><dt>Not refunded</dt><dd>$18.45 for the food, which the restaurant has already prepared.</dd><dt>If you keep it</dt><dd>Alex is about 8 minutes away. If it’s not with you by 1:05 PM, I’ll offer a full refund or Uber Cash.</dd></dl></div>`+actions([['ok','Keep my order',true],['refund','Cancel anyway']])+escalate:bot('<p>Sorry about the wait. Here’s your order and cancellation summary:</p>')+`<div class="outcome-card"><dl><dt>Your order</dt><dd>Will be canceled once you confirm, and the courier will be notified.</dd><dt>Refund</dt><dd><b>$24.80</b> will go back to your original payment, usually within 3–10 business days.</dd><dt>Why you qualify</dt><dd>Your order hasn’t arrived and the courier has been stalled for 10+ minutes.</dd></dl></div>`+actions([['refund','Confirm cancellation',true],['wait','Keep my order']])+escalate}
if(view==='different'){html=bot(`<p>${model.scenario==='past'?'Let’s look at your past order.':'Of course. Let’s focus on what you need.'}</p><p>Tell me what happened in your own words. You don’t have to fit your issue into a category.</p>`)+`<div class="writing-hint"><span>For example</span> “I was charged twice” or “An item was missing.”</div>`}
if(view==='processing'){html=bot('<p>Taking care of that for you…</p><p>Your cancellation and refund are being processed.</p>')+'<div class="processing-line" role="status"><i></i><span>Processing demo refund</span></div>'}
if(view==='receipt'){html=bot(`<p><b>All set.</b> I’ve canceled your order and refunded <b>${model.amount}</b>${model.amount==='$6.35'?' for delivery, fees and tax':''} to your original payment method. It usually arrives within 3–10 business days.</p><p>I’m here if you need anything else.</p>`)+actions([['done','Done',true]])+'<p class="simulation-note">Refunds are simulated in this prototype.</p>'}
if(view==='summary'){html=`<div class="resolution"><div class="celebration"><h3>Issue resolved!</h3><div class="celebration-art"><span class="sparkle s1"></span><span class="sparkle s2"></span><span class="sparkle s3"></span><span class="sparkle s4"></span>${mascot}</div></div><p class="closing-message">Thanks for your patience.</p><p class="rating-title">How was your support experience?</p><div class="stars" role="group" aria-label="Rate your support experience">${[1,2,3,4,5].map(i=>`<button data-rating="${i}" aria-label="${i} star${i>1?'s':''}" aria-pressed="${model.rating===i}" class="${i<=model.rating?'selected':''}">★</button>`).join('')}</div><p class="rating-note" id="rating-note">${model.rating?'Thank you. Your feedback is recorded for this demo.':'Your feedback is valuable to us.'}</p><div class="resolution-help"><span>${icons.person}</span><p>For any other issues, use<br><b>Request human agent</b> above.</p></div></div>`}
if(view==='contacting'){const sent=`<div class="sent-card"><span>Sent to Alex, your courier</span><p>Hi Alex, order #${orderId()} hasn’t moved for over 10 minutes. Could you share an update for the customer?</p></div>`;html=bot('<p>I’ve messaged Alex to check on your order.</p>').replace('class="message"',model.courier?'class="message settled"':'class="message"')+sent+(!model.courier?'<div class="processing-line" role="status"><i></i><span>Waiting for Alex’s reply…</span></div>':model.courier==='replied'?courier('Sorry about the wait! My bike chain broke, but it’s fixed now. I’m about 8 minutes away.')+bot('<p>Good news: Alex is back on the way, about <b>8 minutes</b> out. That’s still before your latest arrival time of <b>1:05 PM</b>.</p><p>I’ll keep an eye on it. If it’s not with you by 1:05 PM, I’ll message you right away with a full refund or Uber Cash. You won’t have to ask.</p>')+actions([['ok','Keep my order',true],['cancel','Cancel anyway']])+escalate:bot('<p>Sorry about the wait. Alex hasn’t replied in 2 minutes, and your order is stuck.</p><p>Here are two ways I can make it right:</p>')+actions([['keepcash','Keep my order + $5 Uber Cash'],['refund','Cancel for a full $24.80 refund']])+escalate)}
if(view==='waiting'){html=bot(model.cash?'<p>Done. <b>$5 Uber Cash</b> is in your account and applies automatically to your next order.</p><p>Your order stays active. I’ll keep watching and message you here as soon as Alex moves.</p>':model.courier==='replied'?'<p>Great, your order is on its way.</p><p>I’ll keep watching. If it’s not with you by <b>1:05 PM</b>, I’ll message you here with a full refund or Uber Cash.</p>':'<p>Got it. Your order stays active.</p><p>I’ll keep an eye on it and message you here if anything changes.</p>')+actions(model.cash?[['done','Done',true]]:[['done','Done',true],['cancel','Cancel this order instead']])+escalate}
if(view==='review'){html=bot(`<p>${model.topic==='Payment or charge'?'An unexpected charge is worrying.':model.topic==='Missing or incorrect item'?'I’m sorry your order wasn’t right.':'Thank you for explaining what happened.'}</p><p>I’ve kept your description below. A person can review this with the conversation attached.</p>`)+`<div class="issue-note"><span>YOUR DESCRIPTION</span><p>${esc(model.issue)}</p></div>`+actions([['handoff','Request human review',true],['edit','Add more detail']])}
if(view==='clarify'){html=bot(model.unknowns>1?'<p>I’m sorry I haven’t understood this clearly. Let’s get a person to review your messages so you don’t have to repeat them.</p>':'<p>I’ve kept your message. I don’t have enough information to choose the right solution yet.</p><p>What happened, and what would help make it right? You can also request a person above.</p>')+(model.unknowns>1?actions([['handoff','Continue with a person',true]]):'')}
if(view==='handoff'){html=bot('<p>Let’s get you to a person.</p><p>Your order, messages, and actions so far are included. <b>You won’t need to explain everything again.</b></p>')+contextCard()+`<div class="queue-status"><i></i><div><b>Ready for a support specialist</b><span>Demo handoff · No live queue or wait estimate</span></div></div>`+actions([['join','Preview agent joining',true],['return','Continue with AI']])}
if(view==='agent'){html=`<div class="agent-arrival"><span class="agent-avatar">${icons.person}</span><div><b>Jamie has joined</b><span>Human support · Simulated conversation</span></div></div>`+agent(`<p>Hi, I’m Jamie. I’ve read your conversation about <b>${esc((model.topic||(model.scenario==='active'?'your delivery':'your past order')).toLowerCase())}</b>.</p><p>${model.issue?`I have your description: “${esc(model.issue)}”`:'I have your order details and the support actions so far.'}</p><p>You don’t need to repeat that. Is there anything you’d like to add?</p>`)+model.agentMessages.map(m=>m.who==='You'?`<div class="message user-message"><div class="bubble">${esc(m.text)}</div></div>`:agent(`<p>${esc(m.text)}</p>`)).join('')}
renderRationale(view);chat.innerHTML=html+(model.notice?`<p class="inline-notice" role="status">${esc(model.notice)}</p>`:'');chat.scrollTop=view==='agent'||(view==='contacting'&&model.courier)?chat.scrollHeight:0;$('history').disabled=!model.transcript.length;
}
function start(){if(model.refund){go('receipt');return}if(model.scenario==='active'){log('You','Get help with this order');model.topic='Delayed delivery';say('Your courier hasn’t moved in over 10 minutes. Options: contact my courier, cancel this order, or something else.');go('options')}else{say('Let’s look at your past order. Tell me what happened in your own words.');go('different')}}
function elsewhere(){if(model.refund){go('receipt');return}log('You','I need help with something else');say('Tell me what happened in your own words.');go('different');input.focus()}
function openHandoff(){if(['handoff','agent'].includes(model.view))return;model.returnView=model.view==='entry'?(model.scenario==='active'?'options':'different'):model.view;say('Your order, messages, and actions so far will go to a support specialist.');go('handoff')}
function issue(text){model.issue=model.issue?`${model.issue}\n${text}`:text}
function refund(){if(model.refund){go('receipt');return}if(model.scenario!=='active'||model.processing)return;log('You',partial()?'Cancel anyway':'Confirm cancellation');model.amount=refundAmount();model.processing=true;go('processing');timer=setTimeout(()=>{model.refund=true;model.processing=false;say(`Order canceled. ${model.amount} refunded to the original payment method.`);if(model.view==='processing'){go('receipt',{remember:false})}else{render()}},900)}
function back(){if(model.processing)return;let previous=model.stack.pop()||'entry';if(model.refund&&['welcome','options','confirm','processing','waiting'].includes(previous))previous='receipt';go(previous,{remember:false})}
const handlers={start,elsewhere,help:()=>{if(model.scenario==='past'){go('different');return}go('options')},contact:()=>{if(model.scenario!=='active'||model.refund)return;clearTimeout(timer);log('You','Contact my courier');say(`Message sent to courier Alex about order #${orderId()}.`);model.courier='';model.view==='contacting'?render():go('contacting');timer=setTimeout(()=>{model.courier=model.silent?'silent':'replied';say(model.silent?'Alex hasn’t replied in 2 minutes. Offered: keep the order with $5 Uber Cash, or cancel for a full $24.80 refund.':'Alex replied: back on the way, about 8 minutes out, before the 1:05 PM latest arrival. I’ll watch it and offer a full refund or Uber Cash if it’s late.');if(model.view==='contacting')render()},2500)},ok:()=>{log('You','Keep my order');say('Order stays active. I’ll watch it and offer a full refund or Uber Cash if it isn’t delivered by 1:05 PM.');go('waiting')},keepcash:()=>{if(model.refund||model.cash)return;log('You','Keep my order + $5 Uber Cash');model.cash=5;say('Order kept. $5 Uber Cash added to the account.');go('waiting')},wait:()=>{if(model.scenario!=='active'||model.refund)return;log('You','Keep waiting');say('Your order stays active. I’ll update you when the courier moves.');go('waiting')},cancel:()=>{if(model.refund){go('receipt');return}if(model.scenario!=='active'||model.cash)return;log('You',partial()?'Cancel anyway':'Cancel this order');say(partial()?'If you cancel now: $6.35 refunded for delivery, fees and tax; the $18.45 food cost is not refunded.':'If you cancel: order canceled, $24.80 refunded to the original payment in 3–10 business days.');go('confirm')},different:()=>{log('You','I need help with something else');say('Tell me what happened in your own words.');go('different');input.focus()},refund,done:()=>{log('You','Done');say('Issue resolved. Thanks for your patience.');go('summary')},handoff:openHandoff,join:()=>{log('Jamie · demo specialist',`I have read your conversation and description: ${currentIssue()}`);go('agent')},return:()=>go(model.refund&&model.returnView==='processing'?'receipt':model.returnView),edit:()=>{go('different');input.focus()},tracking:()=>go('entry')};
chat.addEventListener('click',e=>{const star=e.target.closest('[data-rating]');if(star){model.rating=Number(star.dataset.rating);chat.querySelectorAll('[data-rating]').forEach(b=>{b.classList.toggle('selected',Number(b.dataset.rating)<=model.rating);b.setAttribute('aria-pressed',Number(b.dataset.rating)===model.rating?'true':'false')});$('rating-note').textContent=`Thank you for your ${model.rating}-star rating. Recorded for this demo.`;return}const action=e.target.closest('[data-action]');if(action&&handlers[action.dataset.action])handlers[action.dataset.action]()});
$('composer').addEventListener('submit',e=>{e.preventDefault();const text=input.value.trim();if(!text||model.processing)return;input.value='';log('You',text);
if(model.view==='agent'){model.agentMessages.push({who:'You',text});const reply='Thank you — I’ve added that to your case. In a live service, your specialist would review it and follow up here.';model.agentMessages.push({who:'Jamie',text:reply});log('Jamie · demo specialist',reply);render();return}
if(model.view==='handoff'){issue(text);say('Additional details added to the handoff.');render();return}
if(/\b(human|person|agent|representative)\b/i.test(text)){if(text.split(/\s+/).length>5)issue(text);openHandoff();return}
if(/\b(don['’]?t|do not|not|no need to)\s+(want to\s+|need to\s+)?(cancel|refund)\b|keep (my |the )?order|\b(i['’]?ll|i will|i can|happy to|let me) wait\b/i.test(text)&&model.scenario==='active'&&!model.refund){issue(text);handlers.wait();return}
if(model.view==='review'){issue(text);say('Your additional details have been kept for review.');go('review',{remember:false});return}
if(/charg|payment|paid|bill|refund not|refund.*(missing|received)|haven.t.*refund/i.test(text)){model.topic='Payment or charge';issue(text);say('Your payment concern and description are ready for human review.');go('review');return}
if(/missing|wrong|incorrect|cold|damaged|item|food/i.test(text)&&!/(refund|cancel)/i.test(text)){model.topic='Missing or incorrect item';issue(text);say('Your order issue and description are ready for human review.');go('review');return}
if(/\b(refund|cancel)\b/i.test(text)){if(model.refund){go('receipt');return}issue(text);if(model.scenario==='active'){model.topic='Delayed delivery';handlers.cancel()}else{model.topic='Past-order refund request';say('Your past-order refund request needs review.');go('review')}return}
if(/\b(done|thanks|thank you|resolved|solved)\b/i.test(text)&&model.refund){handlers.done();return}
if(/delay|courier|driver|late|not mov/i.test(text)&&model.scenario==='active'&&!model.refund){issue(text);model.topic='Delayed delivery';say('Let’s review the options for your delayed delivery.');go('options');return}
issue(text);if(model.view==='different'){model.topic='Other order issue';say('Your description is ready for a specialist to review.');go('review');return}
model.unknowns++;say(model.unknowns>1?'I haven’t understood clearly. A person can review your messages without you repeating them.':'I’ve kept your message. What happened, and what would help make it right?');go('clarify');
});
$('human').onclick=openHandoff;$('back').onclick=back;$('reset').onclick=()=>fresh($('scenario').value);$('scenario').onchange=e=>fresh(e.target.value);$('order-help').onclick=()=>{document.querySelector('.support').scrollIntoView({behavior:'smooth',block:'start'});if(model.view==='entry')chat.querySelector('.entry-choice')?.focus({preventScroll:true})};
$('order-details').onclick=$('order-chip').onclick=()=>$('details').showModal();$('close-details').onclick=()=>$('details').close();$('done-details').onclick=()=>$('details').close();$('history').onclick=()=>{$('transcript').innerHTML=model.transcript.map(m=>`<div class="transcript-message"><b>${esc(m.who)}</b><p>${esc(m.text)}</p></div>`).join('');$('history-dialog').showModal()};$('close-history').onclick=()=>$('history-dialog').close();
for(const dialog of document.querySelectorAll('dialog'))dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
fresh();
